+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} stores the violations of every single
+ * {@link FreezingArchRule} in a dedicated file and keeps an index of the
+ * stored rules in the same folder.
+ *
+ * <p>The store can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a naming strategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("(?:\\r\\n|\\r|\\n)*");
+
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+
+    private static final String RANDOM_FILE_NAMES = "random";
+    private static final String DESCRIPTION_FILE_NAMES = "description";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+    private static final String INTEGRITY_IGNORE = "ignore";
+
+    /* A lock is deliberately keyed by the canonical folder, not by the spelling of its path. */
+    private static final ConcurrentHashMap<String, Object> LOCKS_BY_PATH = new ConcurrentHashMap<>();
+    private static final ConcurrentHashMap<String, StoreState> STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean strategyWasPassedToConstructor;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private Path storeFolder;
+    private Path storeFolderRealPath;
+    private Path storedRulesFile;
+    private Object storeLock;
+    private StoreState storedRules;
+
+    /** Creates a store that names new violation files by random UUIDs. */
+    public TextFileBasedViolationStore() {
+        this(createRandomFileNameStrategy(), false);
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how a rule violation file name is derived
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        this(ruleViolationFileNameStrategy, true);
+    }
+
+    private TextFileBasedViolationStore(RuleViolationFileNameStrategy strategy, boolean passedToConstructor) {
+        constructorStrategy = checkNotNull(strategy);
+        strategyWasPassedToConstructor = passedToConstructor;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        checkNotNull(properties);
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
+        ruleViolationFileNameStrategy = selectFileNameStrategy(properties);
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        try {
+            storeFolder = Paths.get(path).toAbsolutePath().normalize();
+        } catch (InvalidPathException e) {
+            throw new StoreInitializationFailedException("Invalid violation store path '" + path + "'", e);
+        }
+        storeLock = lockFor(storeFolder);
+
+        synchronized (storeLock) {
+            prepareFolderAndIndex();
+            storedRules = stateFor(storeFolder);
+            storedRules.reload();
+            if (integrityMode != IntegrityMode.IGNORE) {
+                checkIntegrity();
+            }
+        }
+    }
+
+    private IntegrityMode parseIntegrity(String value) {
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid value '%s' for %s; accepted values are '%s', '%s' and '%s'",
+                value, INTEGRITY_PROPERTY_NAME, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+    }
+
+    private RuleViolationFileNameStrategy selectFileNameStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (strategyWasPassedToConstructor) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a RuleViolationFileNameStrategy was passed to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+        if (configured == null || RANDOM_FILE_NAMES.equals(configured)) {
+            return createRandomFileNameStrategy();
+        }
+        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionFileName;
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s must implement %s", configured, RuleViolationFileNameStrategy.class.getName()));
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot instantiate %s as a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    configured), e);
+        }
+    }
+
+    private static RuleViolationFileNameStrategy createRandomFileNameStrategy() {
+        return ignored -> UUID.randomUUID().toString();
+    }
+
+    private static String createDescriptionFileName(String description) {
+        String candidate = null;
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description == null ? "" : description);
+        while (matcher.find()) {
+            String word = matcher.group(1);
+            if (candidate == null || word.length() > candidate.length()) {
+                candidate = word;
+            }
+        }
+        if (candidate == null) {
+            candidate = "rule";
+        }
+        String digest = digest(description == null ? "" : description);
+        String suffix = "-" + digest;
+        int maxBaseLength = 200 - suffix.length();
+        if (candidate.length() > maxBaseLength) {
+            candidate = candidate.substring(0, maxBaseLength);
+        }
+        String result = candidate + suffix;
+        return STORED_RULES_FILE_NAME.equals(result) ? "rule-" + digest : result;
+    }
+
+    private static String digest(String input) {
+        try {
+            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(input.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(bytes.length * 2);
+            for (byte value : bytes) {
+                result.append(String.format("%02x", value & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private void prepareFolderAndIndex() {
+        storedRulesFile = storeFolder.resolve(STORED_RULES_FILE_NAME);
+        boolean indexExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        try {
+            if (!indexExists) {
+                Files.createDirectories(storeFolder);
+                if (!Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                    Files.createFile(storedRulesFile);
+                }
+            }
+            if (!Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The stored rules index %s is not a regular file directly in the store folder",
+                        storedRulesFile));
+            }
+            if (!Files.isDirectory(storeFolder)) {
+                throw new StoreInitializationFailedException("Violation store path is not a directory: " + storeFolder);
+            }
+            storeFolderRealPath = storeFolder.toRealPath();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException("Cannot initialize violation store at " + storeFolder, e);
+        }
+    }
+
+    private Object lockFor(Path folder) {
+        try {
+            String key = folder.toFile().getCanonicalPath();
+            return LOCKS_BY_PATH.computeIfAbsent(key, ignored -> new Object());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private StoreState stateFor(Path folder) {
+        try {
+            String key = folder.toFile().getCanonicalPath();
+            return STATES_BY_PATH.computeIfAbsent(key, ignored -> new StoreState(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void checkIntegrity() {
+        IntegritySnapshot snapshot = inspectIntegrity();
+        if (integrityMode == IntegrityMode.FAIL) {
+            if (snapshot.hasProblems()) {
+                throw new StoreInitializationFailedException(snapshot.failureMessage(storeUpdateAllowed));
+            }
+            return;
+        }
+
+        boolean changed = false;
+        for (Entry entry : snapshot.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteEntryFile(entry, true);
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntryFile(entry);
+                storedRules.put(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            storedRules.persist();
+        }
+    }
+
+    private IntegritySnapshot inspectIntegrity() {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : storedRules.keys()) {
+            String name = storedRules.get(description);
+            String derivedName = requireNameForInitialization(description);
+            entries.add(new Entry(description, name, derivedName));
+        }
+        for (Entry entry : entries) {
+            classifyFile(entry);
+        }
+
+        markShared(entries);
+        markCollisions(entries);
+        markOccupied(entries);
+        List<String> unownedFiles = findUnownedFiles(entries);
+        return new IntegritySnapshot(entries, unownedFiles);
+    }
+
+    private String requireNameForInitialization(String description) {
+        String name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (name == null || name.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return name;
+    }
+
+    private void classifyFile(Entry entry) {
+        Path path = pathFor(entry.name);
+        if (path == null || !isDirectChild(path) || !Files.isRegularFile(path)) {
+            entry.broken = true;
+            entry.realFile = existingRealFile(path);
+            entry.resolved = entry.realFile != null && containsNoViolations(path);
+            return;
+        }
+        entry.realFile = existingRealFile(path);
+        if (entry.realFile == null || !isDirectChild(entry.realFile)) {
+            entry.broken = true;
+        }
+        entry.resolved = containsNoViolations(path);
+    }
+
+    private Path existingRealFile(Path path) {
+        if (path == null || !Files.isRegularFile(path)) {
+            return null;
+        }
+        try {
+            return path.toRealPath();
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private boolean containsNoViolations(Path path) {
+        try {
+            String contents = new String(Files.readAllBytes(path), UTF_8);
+            return ONLY_LINE_BREAKS_PATTERN.matcher(contents).matches();
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void markShared(List<Entry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (first.name.equals(second.name) || sameFile(first.realFile, second.realFile)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private void markCollisions(List<Entry> entries) {
+        Map<String, Integer> counts = new HashMap<>();
+        for (Entry entry : entries) {
+            Integer count = counts.get(entry.derivedName);
+            counts.put(entry.derivedName, count == null ? 1 : count + 1);
+        }
+        for (Entry entry : entries) {
+            entry.colliding = counts.get(entry.derivedName) > 1;
+        }
+    }
+
+    private void markOccupied(List<Entry> entries) {
+        for (Entry entry : entries) {
+            if (!entry.misplaced()) {
+                continue;
+            }
+            Path derivedPath = pathFor(entry.derivedName);
+            boolean occupied = false;
+            if (derivedPath == null || !isDirectChild(derivedPath) || derivedPath.equals(storedRulesFile)) {
+                occupied = true;
+            } else if (existsWithoutFollowing(derivedPath)) {
+                occupied = true;
+            }
+            for (Entry other : entries) {
+                if (other != entry && other.name.equals(entry.derivedName)) {
+                    occupied = true;
+                }
+            }
+            if (derivedPath != null && existsWithoutFollowing(derivedPath)) {
+                Path real = existingRealFile(derivedPath);
+                if (real != null && !isDirectChild(real)) {
+                    occupied = true;
+                }
+            }
+            entry.occupied = occupied;
+        }
+    }
+
+    private List<String> findUnownedFiles(List<Entry> entries) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder)) {
+            for (Path file : files) {
+                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) || sameFile(file, storedRulesFile)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (sameFile(file, entry.realFile)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException("Cannot inspect violation store folder " + storeFolder, e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private boolean sameFile(Path first, Path second) {
+        if (first == null || second == null) {
+            return false;
+        }
+        try {
+            return Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private String integrityFailureMessage(List<Entry> entries, List<String> unownedFiles, boolean allowUpdate) {
+        StringBuilder result = new StringBuilder();
+        result.append("Violation store integrity check failed (default.allowStoreUpdate=")
+                .append(allowUpdate).append(")");
+        appendEntries(result, "broken", entries, entry -> entry.broken);
+        appendEntries(result, "resolved", entries, entry -> entry.resolved);
+        appendEntries(result, "shared", entries, entry -> entry.shared);
+        appendEntries(result, "misplaced", entries, entry -> entry.misplaced());
+        appendEntries(result, "colliding", entries, entry -> entry.colliding);
+        appendEntries(result, "occupied", entries, entry -> entry.occupied);
+        if (!unownedFiles.isEmpty()) {
+            result.append("\nunowned files:");
+            for (String file : unownedFiles) {
+                result.append("\n- ").append(file);
+            }
+        }
+        return result.toString();
+    }
+
+    private void appendEntries(StringBuilder result, String condition, List<Entry> entries, EntryCondition predicate) {
+        List<Entry> matching = entries.stream().filter(predicate::matches)
+                .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
+        if (!matching.isEmpty()) {
+            result.append("\n").append(condition).append(" entries:");
+            for (Entry entry : matching) {
+                result.append("\n- ").append(entry.description).append(" -> ").append(entry.name);
+            }
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeLock) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storeLock) {
+            saveLocked(rule.getDescription(), violations);
+        }
+    }
+
+    private void saveLocked(String description, List<String> violations) {
+        String derivedName = requireNameForUpdate(description);
+        String recordedName = storedRules.get(description);
+        String targetName = recordedName == null ? derivedName : recordedName;
+        Path target = validateSaveTarget(targetName);
+
+        if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && recordedName != null) {
+            Entry entry = new Entry(description, recordedName, derivedName);
+            classifyFile(entry);
+            List<Entry> entries = entriesForSharing();
+            if (!isSharedWithAnotherEntry(entry, entries)) {
+                deleteEntryFile(entry, false);
+            }
+            storedRules.remove(description);
+            storedRules.persist();
+            return;
+        }
+
+        byte[] contents = serializeViolations(violations);
+        boolean existed = existsWithoutFollowing(target);
+        byte[] previous = null;
+        if (existed && Files.isRegularFile(target)) {
+            try {
+                previous = Files.readAllBytes(target);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        try {
+            if (existed) {
+                Files.write(target, contents, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+            } else {
+                Files.write(target, contents, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
+            }
+            if (recordedName == null) {
+                storedRules.put(description, targetName);
+                try {
+                    storedRules.persist();
+                } catch (RuntimeException e) {
+                    restoreFile(target, existed, previous);
+                    storedRules.remove(description);
+                    throw e;
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String requireNameForUpdate(String description) {
+        String name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (name == null || name.isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return name;
+    }
+
+    private byte[] serializeViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private void restoreFile(Path target, boolean existed, byte[] previous) {
+        try {
+            if (existed && previous != null) {
+                Files.write(target, previous, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+            } else {
+                Files.deleteIfExists(target);
+            }
+        } catch (IOException ignored) {
+            log.warn("Could not roll back violation file {} after an index update failed", target);
+        }
+    }
