    private Object lockFor(Path folder) {
        try {
            String key = folder.toFile().getCanonicalPath();
            return LOCKS_BY_PATH.computeIfAbsent(key, ignored -> new Object());
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private StoreState stateFor(Path folder) {
        try {
            String key = folder.toFile().getCanonicalPath();
            return STATES_BY_PATH.computeIfAbsent(key, ignored -> new StoreState(storedRulesFile));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
