    private void checkIntegrity() {
        IntegritySnapshot snapshot = inspectIntegrity();
        if (integrityMode == IntegrityMode.FAIL) {
            if (snapshot.hasProblems()) {
                throw new StoreInitializationFailedException(snapshot.failureMessage(storeUpdateAllowed));
            }
            return;
        }

        boolean changed = false;
        for (Entry entry : snapshot.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                if (entry.resolved && entry.realFile != null) {
                    deleteEntryFile(entry, true);
                }
                storedRules.remove(entry.description);
                changed = true;
            } else if (entry.resolved) {
                deleteEntryFile(entry, true);
                storedRules.remove(entry.description);
                changed = true;
            } else if (entry.misplaced() && !entry.colliding && !entry.occupied) {
                moveEntryFile(entry);
                storedRules.put(entry.description, entry.derivedName);
                changed = true;
            }
        }
        if (changed) {
            storedRules.persist();
        }
    }

    private IntegritySnapshot inspectIntegrity() {
        List<Entry> entries = new ArrayList<>();
        for (String description : storedRules.keys()) {
            String name = storedRules.get(description);
            String derivedName = randomFileNames ? name : requireNameForInitialization(description);
            entries.add(new Entry(description, name, derivedName));
        }
        for (Entry entry : entries) {
            classifyFile(entry);
        }

        markShared(entries);
        markCollisions(entries);
        markOccupied(entries);
        List<String> unownedFiles = findUnownedFiles(entries);
        return new IntegritySnapshot(entries, unownedFiles);
    }

    private String requireNameForInitialization(String description) {
        String name = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (name == null || name.isEmpty()) {
            throw new StoreInitializationFailedException(String.format(
                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
        }
        return name;
    }

    private void classifyFile(Entry entry) {
        Path path = pathFor(entry.name);
        if (path == null || !isDirectChild(path) || path.equals(storedRulesFile)
                || sameFile(path, storedRulesFile) || !Files.isRegularFile(path)) {
            entry.broken = true;
            entry.realFile = existingRealFile(path);
            entry.resolved = entry.realFile != null && containsNoViolations(path);
            return;
        }
        entry.realFile = existingRealFile(path);
        if (entry.realFile == null || !isDirectChildOfRealFolder(entry.realFile)) {
            entry.broken = true;
        }
        entry.resolved = containsNoViolations(path);
    }

    private Path existingRealFile(Path path) {
        if (path == null || !Files.isRegularFile(path)) {
            return null;
        }
        try {
            return path.toRealPath();
        } catch (IOException e) {
            return null;
        }
    }

